#![allow(unused)]
use vstd::prelude::*;

verus! {

    /// Returns true exactly when `n` is strictly greater than every element of `a`.
    /// For an empty slice, returns true.
    fn is_greater(n: i32, a: &[i32]) -> (result: bool)
        ensures
            // result holds exactly when ∀ i < a.len(): n > a[i]
            result == forall|i: usize| i < a.len() ==> n > a[i]
    {
        let mut i: usize = 0;

        // We scan through the slice.  If we ever find a[i] >= n, we immediately return false.
        while i < a.len()
            invariant
                // i stays within bounds
                i <= a.len(),
                // Up to index i, we have maintained that n > a[j] for all j < i
                forall|j: usize| j < i ==> n > a[j]
            decreases
                // We make progress by increasing i
                a.len() - i
        {
            if !(n > a[i]) {
                // Found a counterexample: a[i] >= n
                return false;
            }
            i += 1;
        }

        // If we never found a violating element, return true
        true
    }

    #[verifier::test]
    fn test_is_greater() {
        assert!(is_greater(5, &[]));
        assert!(is_greater(5, &[1, 2, 3, 4]));
        assert!(!is_greater(3, &[1, 2, 3, 4]));
        assert!(!is_greater(0, &[-1, -2, 0]));
    }
}